// Vendored workflow engine: generated by scripts/sync-workflow-engine.mjs, never edited by hand. Source, commit and local patches: lib/workflow-engine/UPSTREAM.json
import type { WorkflowInstance } from './state.ts';

/** Task markers a reader needs to pick the live instance and spot an empty one. */
export const SUMMARY_TASK_KEYS = ['workflow_v2_shape_change_token', 'workflow_v2_empty'] as const;

/**
 * Every field the batch object read touches: what instanceSummary returns and
 * what read authorization (instanceResource) looks at. Stores load only these
 * for that read; the in-memory store applies the same cut so tests see what
 * production sees.
 */
export const SUMMARY_PATHS: readonly string[] = [
  'id', 'organization_id', 'workflow_id', 'created_by', 'created_at', 'updated_at', 'flat_order',
  'object.type', 'object.id', 'steps.id', 'steps.assignee',
  ...SUMMARY_TASK_KEYS.map((key) => `task.${key}`),
  'task.department', 'task.departments', 'task.business_unit',
];

// projectSummaryFields handles one level of nesting, as Mongo's projection
// does for these paths; a deeper path would make the two stores disagree.
const SPLIT_PATHS = SUMMARY_PATHS.map((path) => {
  const parts = path.split('.');
  if (parts.length > 2) throw new Error(`summary path too deep: ${path}`);
  return parts as [string, string?];
});

const isDocument = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null && !Array.isArray(value);

/** An instance cut down to SUMMARY_PATHS (arrays mapped, non-documents dropped). */
export function projectSummaryFields(instance: WorkflowInstance): WorkflowInstance {
  const source = instance as unknown as Record<string, any>;
  const out: Record<string, any> = {};
  for (const [head, field] of SPLIT_PATHS) {
    const value = source[head];
    if (value === undefined) continue;
    if (!field) {
      out[head] = value;
    } else if (Array.isArray(value)) {
      const items = value.filter(isDocument);
      out[head] = items.map((item, index) => ({
        ...(out[head]?.[index] ?? {}),
        ...(field in item ? { [field]: item[field] } : {}),
      }));
    } else if (isDocument(value)) {
      out[head] = { ...(out[head] ?? {}), ...(field in value ? { [field]: value[field] } : {}) };
    }
  }
  return out as WorkflowInstance;
}
